{"file_path":"tests/test_spec.py","content":""""Behavioral tests for each section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_counts_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([{"flagged": None}]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_pooled_weighted_and_empty():
    groups = {"large": [{"flagged": True}] * 3, "small": [{"flagged": False}], "empty": []}
    assert pooled_flag_rate(groups) == 0.75
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


def test_section_3_window_boundaries():
    counts = [1, 2, 3]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 1) == 3
    assert flags_in_window(counts, 2) == 5
    assert flags_in_window(counts, 3) == 6
    assert flags_in_window(counts, 20) == 6
    assert flags_in_window([], 1) == 0


def test_section_4_parse_flags_whitespace_and_skipped_lines():
    lines = [" \n", "  # comment,not,data\n", " a , 1 , 1 ", " b, -2, 0", " c , 3 ,  "]
    assert parse_transcript_log(lines) == [event("a", 1, True), event("b", -2, False), event("c", 3, None)]


@pytest.mark.parametrize("bad", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1,yes"])
def test_section_4_errors_count_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log([" ", "  # comment", bad])


def test_section_5_duplicate_ids_keep_last_then_sort():
    events = [event("a", 1, True), event("b", 3, True), event("a", 3, None), event("c", 2, False)]
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]
    assert dedupe_transcripts([]) == []


def test_section_6_inclusive_range_missing_and_outside_days():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_section_7_summary_uses_calendar_days_and_pooled_rate():
    groups = {"a": [event("a", 1, True), event("b", 3, False)],
              "b": [event("c", 3, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_rank_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}],
              "a": [{"flagged": True}], "c": [{"flagged": None}]}
    assert top_flagged_groups(groups, 3) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 20) == ["a", "z", "b", "c"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 2) == []


def test_section_9_group_rates_include_empty_and_are_sorted():
    groups = {"z": [], "b": [{"flagged": None}], "a": [{"flagged": True}, {"flagged": False}]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.5, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


def test_section_10_longest_positive_streak():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6, 0, 1]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
